"""Operator-first dashboard for non-technical Local Life users."""

OPERATOR_DASHBOARD = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Local Life Waste Measurement</title>
<style>
:root{--bg:#f4f7f6;--panel:#fff;--ink:#17221f;--muted:#61706b;--green:#188a64;--green2:#e7f6f0;--amber:#a46500;--amber2:#fff5df;--red:#b42318;--red2:#ffebe9;--blue:#1769aa;--line:#d9e2df;--shadow:0 8px 26px rgba(18,43,35,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Segoe UI,system-ui,sans-serif}button,input{font:inherit}button{cursor:pointer}.app{max-width:1180px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:18px}.brand h1{margin:0;font-size:28px}.brand p{margin:4px 0 0;color:var(--muted)}.status-pill{padding:10px 16px;border-radius:999px;font-weight:800;border:1px solid var(--line);background:#fff}.ok{color:var(--green);background:var(--green2);border-color:#b9e4d5}.warn{color:var(--amber);background:var(--amber2);border-color:#f1d89c}.bad{color:var(--red);background:var(--red2);border-color:#f2beb9}.working{color:var(--blue);background:#eaf4fb;border-color:#bfdcf0}.hero{display:grid;grid-template-columns:1.3fr .7fr;gap:16px}.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:var(--shadow)}.camera-wrap{position:relative;background:#08100d;border-radius:14px;overflow:hidden;min-height:360px;display:flex;align-items:center;justify-content:center}.camera-wrap img{width:100%;display:block;max-height:520px;object-fit:contain}.camera-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.camera-label{font-size:12px;font-weight:800;color:var(--muted);margin:0 0 6px}.camera-grid .camera-wrap{min-height:230px}.current{margin-top:15px;border-radius:14px;padding:16px;background:#f8faf9;border:1px solid var(--line)}.current h2{margin:0 0 10px;font-size:18px}.measurement{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.measure{padding:12px;border-radius:12px;background:#fff;border:1px solid var(--line)}.measure .label,.stat .label{font-size:12px;color:var(--muted);font-weight:700}.measure .value{font-size:22px;font-weight:850;margin-top:3px}.side-title{font-size:18px;margin:0 0 14px}.big-action{width:100%;padding:16px;border:none;border-radius:13px;font-weight:850;font-size:17px;margin-bottom:10px}.primary{background:var(--green);color:#fff}.secondary{background:#eef3f1;color:var(--ink);border:1px solid var(--line)}.danger-soft{background:var(--red2);color:var(--red);border:1px solid #f2beb9}.system-list{margin:14px 0}.sys{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #edf1ef}.sys:last-child{border-bottom:0}.dot{width:11px;height:11px;border-radius:50%;display:inline-block;margin-right:8px;background:#99a5a1}.dot.green{background:var(--green)}.dot.amber{background:#e0a21a}.dot.red{background:var(--red)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.stat{background:#fff;border:1px solid var(--line);border-radius:15px;padding:15px}.stat .number{font-weight:850;font-size:27px;margin-top:4px}.history{margin-top:16px}.history h2{font-size:18px;margin:0 0 12px}.history-list{display:grid;gap:9px}.history-row{display:grid;grid-template-columns:90px 1fr 110px 90px;gap:10px;align-items:center;border:1px solid var(--line);border-radius:12px;padding:11px 13px}.muted{color:var(--muted)}.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:12px}.bottom-actions{display:flex;gap:10px;justify-content:space-between;margin-top:16px;flex-wrap:wrap}.text-btn{border:0;background:transparent;text-decoration:underline;color:var(--muted);padding:8px}.overlay{position:fixed;inset:0;background:rgba(5,12,10,.62);display:none;align-items:center;justify-content:center;padding:18px;z-index:30}.overlay.show{display:flex}.modal{background:#fff;max-width:800px;width:100%;max-height:92vh;overflow:auto;border-radius:20px;padding:22px;box-shadow:0 24px 80px rgba(0,0,0,.28)}.modal.large{max-width:980px}.modal h2{margin:0 0 7px;font-size:24px}.modal p{color:var(--muted)}.stepbar{display:flex;gap:6px;margin:15px 0}.stepdot{height:6px;flex:1;border-radius:8px;background:#dbe3e0}.stepdot.on{background:var(--green)}.wizard-images{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wizard-images img,.roi-stage img{width:100%;background:#0b1310;border-radius:12px;display:block}.checkline{padding:10px 12px;border-radius:10px;margin:8px 0;background:#f7faf8;border:1px solid var(--line)}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px;flex-wrap:wrap}.btn{border:0;border-radius:10px;padding:11px 15px;font-weight:800}.btn.primary{background:var(--green);color:#fff}.btn.secondary{background:#eef3f1;border:1px solid var(--line)}.btn.danger{background:var(--red);color:#fff}.roi-stage{position:relative;display:inline-block;width:100%;user-select:none;touch-action:none}.roi-stage canvas{position:absolute;inset:0;width:100%;height:100%;cursor:crosshair}.field{display:flex;gap:10px;align-items:center;margin:18px 0}.field input{font-size:24px;font-weight:800;width:150px;padding:12px;border:2px solid #bbc9c4;border-radius:10px}.unit{font-weight:800}.callout{border-radius:13px;padding:14px;margin:13px 0;background:var(--green2);border:1px solid #b9e4d5}.callout.warn{background:var(--amber2);border-color:#efd590;color:#6e4700}.callout.bad{background:var(--red2);border-color:#f0bbb6;color:#7e2018}.fix-options{display:grid;grid-template-columns:1fr 1fr;gap:10px}.fix-options button{text-align:left;padding:14px;border:1px solid var(--line);background:#fff;border-radius:12px;font-weight:750}.advanced-link{font-size:13px}.spinner{width:28px;height:28px;border:4px solid #d6e3de;border-top-color:var(--green);border-radius:50%;animation:spin 1s linear infinite;margin:16px auto}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:800px){.hero,.wizard-images{grid-template-columns:1fr}.measurement,.stats{grid-template-columns:1fr}.history-row{grid-template-columns:70px 1fr 80px}.history-row .camera-pair{display:none}.app{padding:12px}.camera-wrap{min-height:240px}}
</style></head>
<body><div class="app">
<div class="top"><div class="brand"><h1>Local Life Waste Measurement</h1><p>Simple operator mode · Accuracy Deployment v3.0</p></div><div id="overall" class="status-pill working">● Starting…</div></div>
<div class="hero">
<section class="card"><div class="camera-grid"><div><div class="camera-label">CAMERA 1 · REALSENSE</div><div class="camera-wrap"><img src="/video/cameras/realsense" alt="RealSense dumpster camera"></div></div><div><div class="camera-label">CAMERA 2 · LOGITECH</div><div class="camera-wrap"><img src="/video/cameras/logitech" alt="Logitech dumpster camera"></div></div></div><div class="current"><h2 id="current-title">Waiting for an item</h2><div class="measurement"><div class="measure"><div class="label">OBJECT ID</div><div id="item-id" class="value">—</div></div><div class="measure"><div class="label">TYPE</div><div id="item-type" class="value">—</div></div><div class="measure"><div class="label">COLOR</div><div id="item-color" class="value">—</div></div><div class="measure"><div class="label">MATERIAL</div><div id="item-material" class="value">—</div></div><div class="measure"><div class="label">SORTING</div><div id="item-sorting" class="value">—</div></div><div class="measure"><div class="label">VOLUME</div><div id="item-volume" class="value">—</div></div><div class="measure"><div class="label">SIZE L×W×H</div><div id="item-dims" class="value">—</div></div><div class="measure"><div class="label">HEIGHT</div><div id="item-height" class="value">—</div></div><div class="measure"><div class="label">CONFIDENCE</div><div id="item-confidence" class="value">—</div></div></div><div id="current-message" class="muted" style="margin-top:10px">Place one bag or box inside the bin when the system is ready.</div></div></section>
<aside class="card"><h2 class="side-title">System</h2><div class="system-list"><div class="sys"><span><span id="dot-mode" class="dot"></span>Processing</span><strong id="txt-mode">Checking</strong></div><div class="sys"><span><span id="dot-vm" class="dot"></span>GPU VM</span><strong id="txt-vm">Checking</strong></div><div class="sys"><span><span id="dot-pi" class="dot"></span>Raspberry Pi</span><strong id="txt-pi">Checking</strong></div><div class="sys"><span><span id="dot-rs" class="dot"></span>Camera 1</span><strong id="txt-rs">Checking</strong></div><div class="sys"><span><span id="dot-log" class="dot"></span>Camera 2</span><strong id="txt-log">Checking</strong></div><div class="sys"><span><span id="dot-cal" class="dot"></span>Setup</span><strong id="txt-cal">Checking</strong></div></div><button class="big-action primary" onclick="startSession()">START NEW SESSION</button><button class="big-action secondary" onclick="openCalibration()">SETUP / RECALIBRATE</button><button class="big-action secondary" onclick="openFix()">FIX A PROBLEM</button><button class="big-action danger-soft" onclick="resetList()">RESET CURRENT LIST</button><a class="big-action secondary" style="display:block;text-align:center;text-decoration:none" href="/api/cameras/realsense/measurements.csv">DOWNLOAD LATEST CSV</a><p id="csv-note" class="muted" style="margin:-4px 0 12px;font-size:13px"></p><a class="big-action secondary" style="display:block;text-align:center;text-decoration:none" href="/research">RESEARCH / ADVANCED MODE</a></aside>
</div>
<section class="stats"><div class="stat"><div class="label">ACCEPTED DROPS</div><div class="number" id="count">0</div></div><div class="stat"><div class="label">OPERATIONAL VOLUME</div><div class="number" id="fused-total">0.0 L</div></div><div class="stat"><div class="label">CAMERA COLOR AGREEMENT</div><div class="number" id="color-agreement">—</div></div></section><section class="card history"><h2>Totals by bag color</h2><div id="color-summary" class="history-list"></div><div class="bottom-actions"><button class="text-btn" onclick="editColorMap()">Edit color → content meanings</button></div></section>
<section class="card history"><h2>Current session</h2><div class="bottom-actions" style="margin:0 0 12px"><span id="ledger-state" class="muted">Measurement history: —</span><button class="btn secondary" id="ledger-toggle" onclick="toggleLedger()">—</button></div><div id="history-list" class="history-list"></div><div class="bottom-actions"><button class="text-btn" onclick="openResetMenu()">Reset options</button><a class="text-btn advanced-link" href="/research">Open research / advanced mode</a></div></section>
</div>

<div id="wizard-overlay" class="overlay"><div class="modal large"><h2 id="wizard-title">Setup</h2><p id="wizard-sub"></p><div class="stepbar" id="stepbar"></div><div id="wizard-body"></div><div class="modal-actions"><button class="btn secondary" onclick="closeWizard()">Cancel</button><button id="wizard-back" class="btn secondary" onclick="wizardBack()">Back</button><button id="wizard-next" class="btn primary" onclick="wizardNext()">Continue</button></div></div></div>
<div id="dialog-overlay" class="overlay"><div class="modal"><h2 id="dialog-title"></h2><div id="dialog-body"></div><div id="dialog-actions" class="modal-actions"></div></div></div>
<script>
const $=id=>document.getElementById(id); let state=null, wizardStep=0, roi=[.1,.1,.8,.8], drawing=false, startPoint=null;
const fmt=x=>x==null?'—':Number(x).toFixed(1)+' L';
const API_TOKEN={{ api_token|tojson }};
function authHeaders(extra){const h=Object.assign({},extra||{});if(API_TOKEN)h['X-API-Token']=API_TOKEN;return h}
async function api(url,payload){const r=await fetch(url,{method:payload===undefined?'GET':'POST',headers:authHeaders(payload===undefined?{}:{'Content-Type':'application/json'}),body:payload===undefined?undefined:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function latest(camera){return state?.cameras?.[camera]||{}} function frames(camera){return Number(latest(camera).frames_processed||0)}
function readyInfo(){const rs=latest('realsense'),lg=latest('logitech');const tilt=lg.reference_plane?.tilt_degrees;return{rsFrame:frames('realsense')>0,lgFrame:frames('logitech')>0,rsBase:Number(rs.baseline_frame_count||0)>0,lgBase:Number(lg.baseline_frame_count||0)>0,distance:Number(lg.reference_distance_m||0)>0,tiltOk:tilt==null||tilt<=35,tilt:tilt};}
function setDot(id,good,label){$(id).className='dot '+(good?'green':'red'); if(label)$(id.replace('dot-','txt-')).textContent=label}
function combinedHistory(){return (state?.comparison?.pairs||[]).map(p=>({t:p.matched_at,type:p.object_type,color:p.operational_color||p.realsense_color||p.logitech_color,rs:p.realsense_volume_l,log:p.logitech_volume_l,fused:p.fused_volume_l,reliability:p.fusion_reliability})).sort((x,y)=>y.t-x.t)}
function render(){if(!state)return;const info=readyInfo();const cloud=state.cloud||{};const cloudOn=!!cloud.enabled;$('dot-mode').className='dot '+(cloudOn?'green':'amber');$('txt-mode').textContent=cloudOn?'Cloud GPU':'Local';const vm=cloud.vm_status||(cloudOn?'unknown':'not used');$('dot-vm').className='dot '+(cloudOn?(vm==='running'?'green':'amber'):'');$('txt-vm').textContent=String(vm);const piSeen=frames('realsense')>0||frames('logitech')>0;$('dot-pi').className='dot '+(piSeen?'green':'red');$('txt-pi').textContent=piSeen?'Sending frames':'No frames';setDot('dot-rs',info.rsFrame,info.rsFrame?'Connected':'Not connected');setDot('dot-log',info.lgFrame,info.lgFrame?'Connected':'Not connected');const setup=info.rsBase&&info.lgBase&&info.distance&&info.tiltOk;$('dot-cal').className='dot '+(setup?'green':'amber');$('txt-cal').textContent=setup?'Ready':'Action needed';$('overall').className='status-pill '+(setup&&info.rsFrame&&info.lgFrame?'ok':'warn');$('overall').textContent=setup&&info.rsFrame&&info.lgFrame?'● READY':'● ACTION NEEDED';const rs=latest('realsense'),lg=latest('logitech');const det=(rs.latest?.detections||[])[0]||(lg.latest?.detections||[])[0];if(det){$('current-title').textContent='Item detected';$('item-type').textContent=(det.label||det.object_type||'Item').toUpperCase();$('item-color').textContent=(det.color||'Unknown')+(det.color_confidence!=null?' · '+Math.round(det.color_confidence*100)+'%':'');$('item-id').textContent=det.track_id!=null?'#'+det.track_id:'—';$('item-material').textContent=(det.material||'unknown').toUpperCase();$('item-sorting').textContent={correct:'CORRECT',mis_sort:'MIS-SORT'}[det.sorting_status]||'UNKNOWN';const dm=det.dimensions_mm||det.box_dimensions_mm;$('item-dims').textContent=dm&&dm.length!=null?[dm.length,dm.width,dm.height].map(v=>Math.round(v)).join(' × ')+' mm':'—';$('item-height').textContent=det.height_above_baseline_cm!=null?Number(det.height_above_baseline_cm).toFixed(1)+' cm':'—';$('item-confidence').textContent=det.confidence!=null?Math.round(det.confidence*100)+'%':'—';const rv=rs.latest?.realsense_volume_l,lv=lg.latest?.monocular_volume_l;$('item-volume').textContent=rv!=null&&lv!=null?Number(rv).toFixed(1)+' / '+Number(lv).toFixed(1)+' L':fmt(rv??lv);const reason=det.volume_rejection_reason||(det.measurement_quality&&String(det.measurement_quality).startsWith('rejected')?det.measurement_quality:null);$('current-message').textContent=reason?('Not recorded — '+String(reason).replaceAll('_',' ').replaceAll('-',' ')):(rv!=null||lv!=null?'Two independent measurements are being checked. Keep the bag still until the drop is accepted.':'Keep the bag still while the system measures it.')}else{$('current-title').textContent=setup?'Ready for the next bag':'Setup required';for(const k of ['item-id','item-type','item-color','item-material','item-sorting','item-volume','item-dims','item-height','item-confidence'])$(k).textContent='—';$('current-message').textContent=setup?'Drop one bag into the dumpster.':'Press SETUP / RECALIBRATE and follow the guided steps.'}const saved=Number(rs.measurements_recorded||0);const persist=rs.csv_persistence||{};const lastWrite=persist.last_write_at?new Date(persist.last_write_at*1000).toLocaleTimeString():'never';const csvMeta=$('csv-meta');if(csvMeta){csvMeta.textContent='Recorded measurements: '+saved+' \u00b7 Last CSV write: '+lastWrite+(persist.healthy===false?' \u00b7 WRITE ERROR - queued for retry':'')}const csvNote=$('csv-note');if(csvNote){csvNote.textContent=saved?(saved+' measurement'+(saved===1?'':'s')+' saved to CSV this session.'):(setup?'No completed measurements recorded yet. Place one object and keep it still until a volume appears.':'No completed measurements recorded. Volume needs the empty-bin baseline \u2014 press SETUP / RECALIBRATE with the bin empty.')}const op=state.comparison?.operational||{};$('count').textContent=op.deposited_count||0;$('fused-total').textContent=fmt(op.cumulative_volume_l||0);$('color-agreement').textContent=state.comparison?.color_agreement_percent==null?'—':Number(state.comparison.color_agreement_percent).toFixed(0)+'%';const cs=$('color-summary');cs.replaceChildren();const colors=op.colors||[];if(!colors.length){const e=document.createElement('div');e.className='empty';e.textContent='No matched dumpster drops recorded yet.';cs.appendChild(e)}for(const x of colors){const d=document.createElement('div');d.className='history-row';d.innerHTML='<strong>'+String(x.color||'unknown').toUpperCase()+'</strong><span><strong>'+(x.waste_stream||'Not assigned')+'</strong><br><span class="muted">Editable mapping</span></span><span>'+x.count+' bags</span><strong>'+fmt(x.volume_l)+'</strong>';cs.appendChild(d)}const ledgerOn=!!(latest('realsense').waste_ledger_enabled);$('ledger-state').textContent='Measurement history: '+(ledgerOn?'ON — accepted drops are recorded to CSV':'OFF — nothing is being recorded');$('ledger-toggle').textContent=ledgerOn?'DISABLE HISTORY':'ENABLE HISTORY';const list=$('history-list');list.replaceChildren();const h=combinedHistory();if(!h.length){const e=document.createElement('div');e.className='empty';e.textContent='No accepted drops in this session yet.';list.appendChild(e)}for(const x of h.slice(0,30)){const d=document.createElement('div');d.className='history-row';d.innerHTML='<strong>'+new Date(x.t*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+'</strong><span><strong>'+String(x.type||'item').toUpperCase()+'</strong><br><span class="muted">'+(x.color||'Unknown color')+'</span></span><span class="camera-pair">C1 '+fmt(x.rs)+'<br>C2 '+fmt(x.log)+'</span><strong>'+fmt(x.fused)+'</strong>';list.appendChild(d)}}
async function refresh(){try{state=await api('/api/state');render()}catch(e){$('overall').className='status-pill bad';$('overall').textContent='● CONNECTION LOST'}} setInterval(refresh,1200);refresh();
function showDialog(title,html,buttons){$('dialog-title').textContent=title;$('dialog-body').innerHTML=html;const a=$('dialog-actions');a.replaceChildren();for(const b of buttons){const x=document.createElement('button');x.className='btn '+(b.kind||'secondary');x.textContent=b.text;x.onclick=b.action;a.appendChild(x)}$('dialog-overlay').classList.add('show')}function closeDialog(){$('dialog-overlay').classList.remove('show')}
async function startSession(){showDialog('Start a new session?','<p>This resets both camera item lists and totals to zero. Camera setup is kept. A backup of the previous session is saved automatically.</p>',[{text:'Cancel',action:closeDialog},{text:'Start new session',kind:'primary',action:async()=>{try{await api('/api/operator/session/new',{});closeDialog();await refresh()}catch(e){showDialog('Could not start session','<div class="callout bad">'+e.message+'</div>',[{text:'Close',action:closeDialog}])}}}])}
function resetList(){startSession()} function openResetMenu(){showDialog('Reset options','<div class="fix-options"><button onclick="closeDialog();startSession()">Reset current item list and totals</button><button onclick="closeDialog();openCalibration()">Recalibrate cameras</button></div><p>No data is permanently discarded when a new session is started. The previous session is archived.</p>',[{text:'Close',action:closeDialog}])}
function openFix(){if(!state)return;const i=readyInfo();let title='Automatic check found the problem',body='',action=null;if(!i.rsFrame||!i.lgFrame){body='<div class="callout bad">One or both cameras are not sending images.</div><p>Check the USB cables and Raspberry Pi power, then press Check again.</p>';action=refresh}else if(!i.distance){body='<div class="callout warn">The webcam height has not been entered yet.</div><p>We will take you directly to that setup step.</p>';action=()=>{closeDialog();openCalibration(2)}}else if(!i.rsBase||!i.lgBase){body='<div class="callout warn">The empty-bin reference is missing.</div><p>Remove all objects from the bin and capture the empty bin again.</p>';action=()=>{closeDialog();openCalibration(3)}}else if(!i.tiltOk){body='<div class="callout warn">Camera 2 is pointing too far sideways ('+Number(i.tilt).toFixed(1)+'°).</div><p>Move it closer to straight down, then run setup again.</p>';action=()=>{closeDialog();openCalibration(1)}}else{title='System check';body='<div class="callout">The basic camera and setup checks are OK.</div><p>If a measurement still looks wrong, recalibrate the empty bin and test with one plain box.</p>';action=()=>{closeDialog();openCalibration(3)}}showDialog(title,body,[{text:'Close',action:closeDialog},{text:(!i.rsFrame||!i.lgFrame)?'Check again':'Fix now',kind:'primary',action}])}

async function toggleLedger(){const on=!!(latest('realsense').waste_ledger_enabled);try{await api('/api/waste-ledger',{enabled:!on});await refresh()}catch(e){alert('Could not change the measurement history: '+e.message)}}
function editColorMap(){const current=state?.comparison?.operational?.color_map||{};const colors=['blue','green','yellow','black','red','orange','brown','white','grey','cyan','purple','pink'];let html='<p>These meanings are operational labels only. Camera-detected color remains unchanged in the raw record.</p>';for(const c of colors){html+='<div class="field"><strong style="width:85px">'+c.toUpperCase()+'</strong><input style="font-size:16px;width:100%" id="map-'+c+'" value="'+(current[c]||'')+'" placeholder="e.g. Plastic"></div>'}showDialog('Bag color meanings',html,[{text:'Cancel',action:closeDialog},{text:'Save',kind:'primary',action:async()=>{const mapping={};for(const c of colors){const v=$('map-'+c).value.trim();if(v)mapping[c]=v}try{await api('/api/color-map',{mapping});closeDialog();await refresh()}catch(e){alert(e.message)}}}])}
function openCalibration(step=0){wizardStep=step;$('wizard-overlay').classList.add('show');renderWizard()}function closeWizard(){$('wizard-overlay').classList.remove('show')}function wizardBack(){if(wizardStep>0){wizardStep--;renderWizard()}}async function wizardNext(){try{if(wizardStep===1){await api('/api/cameras/logitech/roi',{roi});wizardStep++}else if(wizardStep===2){const cm=Number($('distance-cm').value);if(!Number.isFinite(cm)||cm<10||cm>500)throw Error('Enter the measured distance in centimeters.');await api('/api/cameras/logitech/reference-distance',{distance_m:cm/100});wizardStep++}else if(wizardStep===3){$('wizard-next').disabled=true;$('wizard-next').textContent='Capturing…';await api('/api/cameras/realsense/baseline',{});await new Promise(r=>setTimeout(r,800));await api('/api/cameras/logitech/baseline',{});await refresh();wizardStep++}else if(wizardStep===4){closeWizard();return}else wizardStep++;renderWizard()}catch(e){showDialog('Setup needs attention','<div class="callout bad">'+e.message+'</div>',[{text:'OK',action:closeDialog}])}finally{$('wizard-next').disabled=false;$('wizard-next').textContent='Continue'}}
function renderWizard(){const titles=['Check the cameras','Select the waste bin','Measure camera height','Save the empty bin','Final check'];const subs=['Make sure both camera pictures show the same waste area.','Draw a box around the inside of the waste bin in Camera 2.','Measure from the front of Camera 2 to the empty bin floor.','The bin must be completely empty for this step.','The system checks that everything needed for measurement is ready.'];$('wizard-title').textContent='Setup — '+titles[wizardStep];$('wizard-sub').textContent=subs[wizardStep];const sb=$('stepbar');sb.replaceChildren();for(let n=0;n<5;n++){const d=document.createElement('div');d.className='stepdot '+(n<=wizardStep?'on':'');sb.appendChild(d)}$('wizard-back').style.visibility=wizardStep?'visible':'hidden';$('wizard-next').textContent=wizardStep===4?'Finish':'Continue';const b=$('wizard-body');if(wizardStep===0)b.innerHTML='<div class="wizard-images"><div><strong>Camera 1</strong><img src="/video/cameras/realsense"></div><div><strong>Camera 2</strong><img src="/video/cameras/logitech"></div></div><div class="checkline">✓ The bin should be visible in both pictures.</div><div class="checkline">✓ Keep both cameras fixed once setup is complete.</div>';else if(wizardStep===1){b.innerHTML='<div class="callout">Click and drag over Camera 2 to draw a rectangle around only the inside of the waste bin. You can redraw it as many times as needed.</div><div class="roi-stage"><img id="roi-img" src="/video/cameras/logitech"><canvas id="roi-canvas"></canvas></div>';setTimeout(setupCanvas,80)}else if(wizardStep===2){const current=Number(latest('logitech').reference_distance_m||0);b.innerHTML='<div class="callout">Use a tape measure. Measure from the front of Camera 2 lens straight down to the empty bin floor.</div><div class="field"><input id="distance-cm" type="number" min="10" max="500" step="0.1" value="'+(current?current*100:'')+'"><span class="unit">cm</span></div><p>Enter centimeters. The software converts the value automatically.</p>'}else if(wizardStep===3)b.innerHTML='<div class="callout warn"><strong>Before continuing:</strong><br>Remove all bags, boxes, hands, tape measures and tools. Leave the bin itself in place. Do not move either camera.</div><div class="wizard-images"><div><strong>Camera 1</strong><img src="/video/cameras/realsense"></div><div><strong>Camera 2</strong><img src="/video/cameras/logitech"></div></div><p>Press Continue to capture the empty bin for both cameras.</p>';else{const i=readyInfo();b.innerHTML='<div class="checkline">'+(i.rsFrame?'✓':'✗')+' Camera 1 connected</div><div class="checkline">'+(i.lgFrame?'✓':'✗')+' Camera 2 connected</div><div class="checkline">'+(i.distance?'✓':'✗')+' Camera height saved</div><div class="checkline">'+(i.rsBase&&i.lgBase?'✓':'✗')+' Empty bin saved</div><div class="checkline">'+(i.tiltOk?'✓':'✗')+' Camera position acceptable'+(i.tilt==null?'':' ('+Number(i.tilt).toFixed(1)+'°)')+'</div><div class="callout '+(i.rsFrame&&i.lgFrame&&i.distance&&i.rsBase&&i.lgBase&&i.tiltOk?'':'warn')+'"><strong>'+(i.rsFrame&&i.lgFrame&&i.distance&&i.rsBase&&i.lgBase&&i.tiltOk?'System ready.':'One or more checks still needs attention.')+'</strong></div>'}}
function setupCanvas(){const img=$('roi-img'),c=$('roi-canvas');if(!img||!c)return;const sync=()=>{c.width=img.clientWidth;c.height=img.clientHeight;drawRoi()};sync();img.onload=sync;window.onresize=sync;c.onpointerdown=e=>{drawing=true;const r=c.getBoundingClientRect();startPoint=[e.clientX-r.left,e.clientY-r.top];roi=[startPoint[0]/c.width,startPoint[1]/c.height,0,0];drawRoi()};c.onpointermove=e=>{if(!drawing)return;const r=c.getBoundingClientRect(),x=Math.max(0,Math.min(c.width,e.clientX-r.left)),y=Math.max(0,Math.min(c.height,e.clientY-r.top));const x0=Math.min(startPoint[0],x),y0=Math.min(startPoint[1],y),x1=Math.max(startPoint[0],x),y1=Math.max(startPoint[1],y);roi=[x0/c.width,y0/c.height,(x1-x0)/c.width,(y1-y0)/c.height];drawRoi()};c.onpointerup=()=>{drawing=false;if(roi[2]<.05||roi[3]<.05)roi=[.1,.1,.8,.8];drawRoi()}}
function drawRoi(){const c=$('roi-canvas');if(!c)return;const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.fillStyle='rgba(0,0,0,.42)';x.fillRect(0,0,c.width,c.height);const [rx,ry,rw,rh]=roi;x.clearRect(rx*c.width,ry*c.height,rw*c.width,rh*c.height);x.strokeStyle='#45e0a8';x.lineWidth=4;x.strokeRect(rx*c.width,ry*c.height,rw*c.width,rh*c.height)}
</script></body></html>'''
